//READ FROM THE UPLOADS GALLERY, WHICH PEXELS PHOTOS AND GRAPHICS DO NOT HAVE: valueFinder THREW ON undefined AND NO HISTORY
//WAS MADE AT ALL (MEASURED 2026-10-04). FOR AN UPLOAD IT WAS THE ORIGINAL FILE, WRONG AFTER A SWAP OR A SECOND SOFT / HARD PASS
function encodeBackground(img, leadPanel, oldSource) {

    let f = Number(leadPanel.dataset.ref);

    let name = leadPanel.querySelector('.txtHeader').value;
    
    let tempHistory = "Remove Background*";
    tempHistory += `\nref: ${f}`;
    tempHistory += `\npnlBoxImage: ${name}`;
    tempHistory += `\nnewImageSource: ${img.src}`;
    tempHistory += `\n_`;
    tempHistory += `\nnewImageSource: ${oldSource}`;

    dataLayer[f] = valueSwitcher(dataLayer[f], 'newImageSource', img.src);

    makeNewHistory(tempHistory);

    /*
    console.clear();
    for(let a = 0; a < 10; a++) {
       console.log(history[a])
    }
    console.log("--------REDO---------")
    for(let a = 0; a < 10; a++) {
       console.log(redoHistory[a])
    }
    */
    
}

async function removeBackground(img, leadPanel, mode) {

    //[!] SAME REQUEST AND RESPONSE SHAPE ON BOTH SERVICES, SAME ai_credits POOL
    //[!] AND SAME 1024/2048/4096 TIERS, SO ONLY THE HOST DIFFERS.
    let ai_model = {
        soft: 'https://withoutbg-supabase-docker-464034045240.asia-southeast1.run.app/',
        hard: 'https://rembg-supabase-dockerfile-464034045240.asia-southeast1.run.app/'
    };

    //[!] FALL BACK TO SOFT SO A CALL WITH NO MODE STILL WORKS
    let url = ai_model[mode] || ai_model.soft;

    const { data: { session }, error } = await wondrSupabase.auth.getSession();
    
    try {

        showLoading();

        let userToken = session.access_token;

        const response = await fetch(url, {
            method: 'POST',  // HTTP method POST
            headers: {
                'Content-Type': 'application/json', 
                'Authorization': `Bearer ${userToken}`,
            },
            body: JSON.stringify({data_sent: img.src}) 
        })
        
       
        const data = await response.json();

        if (response.status == 200) {

            aiCredits = data.remaining_credits;

            //THE UNDO HALF. READ BEFORE THE RESULT LANDS, SO IT IS EXACTLY WHAT WAS ON THE CANVAS
            let oldSource = img.src;

            img.src = data.data_received;
            img.onload = async function() {
            
                hideLoading()

                //[!] PAINT HERE, NOT AT THE ASSIGNMENT ABOVE, SO THE NUMBER DROPS
                //AT THE MOMENT THE RESULT APPEARS AND NOT UNDER THE LOADER
                document.getElementById('lblAiCredits').innerText = aiCredits;

                //encode background to history
                encodeBackground(img, leadPanel, oldSource)
            }
        }
    
        else if (response.status == 402) {

            hideLoading();

            let title = "Daily credits have maxed out";
            let message = "It looks like you've used up all your credits for today. Daily credits reset later at 00:00 UTC.";
            let button1 = "Close";

            let padding = 25;
            let show = showModal(title, message, button1, null, padding);

            if(show) {
            
                let btnModalClose = document.getElementById('btnModalClose');

                btnModalClose.addEventListener('click', e => {
                    hideModal()
                })    
            }
        }
        else if (response.status == 413) {
            hideLoading();

            let title = "Image too large";
            let message = "The image exceeds 4096px on one side. Please resize it and try again.";
            let button1 = "Close";

            let padding = 25;
            let show = showModal(title, message, button1, null, padding);

            if(show) {
            
                let btnModalClose = document.getElementById('btnModalClose');

                btnModalClose.addEventListener('click', e => {
                    hideModal()
                })    
            }
        }
        else {

            hideLoading();

            //[!] ANY OTHER STATUS - 500, 401 ON AN EXPIRED TOKEN, OR 503 FROM A COLD START.
            //[!] THE USER GOT THE SPINNER AND SILENCE, AND SO DID THE CONSOLE

            let title = "Something went wrong";
            let message = "We are unable to process your image this time. Please check your connection and try again.";
            let button1 = "Close";

            let padding = 25;
            let show = showModal(title, message, button1, null, padding);

            if(show) {
            
                let btnModalClose = document.getElementById('btnModalClose');

                btnModalClose.addEventListener('click', e => {
                    hideModal()
                })    
            }
        }  
        
    
    }
    catch(error) {
        
        hideLoading();

        //[!] fetch ITSELF THREW - CONNECTION DROP, DNS, TIMEOUT, OR A NON-JSON BODY
        //[!] (A CLOUD RUN 502 HTML PAGE MAKES response.json() THROW BEFORE THE STATUS
        //[!] CHAIN IS EVEN REACHED). THERE IS NO response HERE, SO THIS IS THE ONLY
        //[!] PLACE IT CAN BE REPORTED

        let title = "Something went wrong";
        let message = "We are unable to process your image this time. Please check your connection and try again.";
        let button1 = "Close";

        let padding = 25;
        let show = showModal(title, message, button1, null, padding);

        if(show) {
        
            let btnModalClose = document.getElementById('btnModalClose');

            btnModalClose.addEventListener('click', e => {
                hideModal()
            })    
        }
    }
        
}

function rcCanvasAddFunction() {

    let i = 0;
    ctrlAFocus = "workArea";
    let rcCanvas = document.getElementById('rcCanvas');
    let rcCanvas2 = document.getElementById('rcCanvas2');

    rcCanvas.querySelectorAll(`[class*='rcOption']`).forEach(opt => {

        let entry = opt.querySelector('h2').innerHTML;

        //USE 'ELECT' TO CHECK IF ENTRY IS SELECT ALL OR DESELECT
        if (entry.toLowerCase().includes('select')) {

            opt.addEventListener('click', function () {
                hideAllContextMenu();
                selectDeselectAll();
            });

            opt.addEventListener('contextmenu', function () {
                hideAllContextMenu();
                selectDeselectAll();
            });

        }
        else if (entry == "Save") {

            opt.addEventListener('click', function () {
                hideAllContextMenu();
                decideHowToDownload();

            });

            opt.addEventListener('contextmenu', function () {
                hideAllContextMenu();
                decideHowToDownload();
            });

        }
        else if (entry == "Download") {

            opt.addEventListener('click', function () {
                hideAllContextMenu();

                //SAME ENTRY POINT AS BTNDOWNLOAD
                convertEnvToImage();

            });

            opt.addEventListener('contextmenu', function () {
                hideAllContextMenu();

                convertEnvToImage();
 
            });
        }
        else if (entry == "Position layer") {

            //THE SECOND pointerenter HERE WAS A COPY WITHOUT ITS e, SO IT THREW ON EVERY HOVER
            opt.addEventListener('pointerenter', function (e) {
                if (rcCanvas2.style.opacity == '0') {

                    hoverArrangeLayers(e, opt);
                }
            });
        }
        else if (entry == "Clone") {

            opt.addEventListener('click', function () {
                hideAllContextMenu();
                cloneCanvas();
            });

            opt.addEventListener('contextmenu', function () {
                hideAllContextMenu();
                cloneCanvas();
            });

        }
        else if (entry == "Paste") {

            opt.addEventListener('click', function () {
                hideAllContextMenu();
                pasteFromClipboard();
            });

            opt.addEventListener('contextmenu', function () {
                hideAllContextMenu();
                pasteFromClipboard();
            });

        }
        else if (entry == "Upload to gallery") {
            
            opt.addEventListener('click', function () {
          
            });

            opt.addEventListener('contextmenu', function () {
               
            });

        }
        else if (entry == "Edit text") {

            opt.addEventListener('click', function () {
                hideAllContextMenu();
                editCanvasTextLayer();
            });

            opt.addEventListener('contextmenu', function () {
                hideAllContextMenu();
                editCanvasTextLayer();
            });

        }
        else if (entry == "Delete") {

            opt.addEventListener('click', function () {
                hideAllContextMenu();
                deleteObject();
            });

            opt.addEventListener('contextmenu', function () {
                hideAllContextMenu();
                deleteObject();
            });
        }
        else if (entry == "Undo") {

            opt.addEventListener('click', function () {
                hideAllContextMenu();
                undo();
            });

            opt.addEventListener('contextmenu', function () {
                hideAllContextMenu();
                undo();
            });
        }
        else if (entry == "Redo") {
            opt.addEventListener('click', function () {
                hideAllContextMenu();
                redo();
            });

            opt.addEventListener('contextmenu', function () {
                hideAllContextMenu();
                redo();
            });
        }
        else if(entry == "Remove background") {

            //[!] PARENT IS HOVER ONLY NOW. THE SUB OPTIONS IN rcCanvas2 DO THE WORK,
            //[!] SO NO click/contextmenu HERE - AND NO HOTKEY, SINCE ONE SHORTCUT
            //[!] CANNOT PICK BETWEEN TWO MODES.
            opt.addEventListener('pointerenter', function (e) {
                if (rcCanvas2.style.opacity == '0') {

                    hoverRemoveBackground(e, opt);
                }
            });
        }

        i++;

        if (i == rcCanvas.querySelectorAll(`[class*='rcOption']`).length) {
            formatContextCanvas();
        }
    });
}

